using System.Security.Cryptography;using System.Text;using DoctorLoan.Application;using DoctorLoan.Application.Interfaces.Commons;using DoctorLoan.Application.Interfaces.Data;using DoctorLoan.Application.Models.Commons;using DoctorLoan.Application.Models.Settings;using DoctorLoan.Domain.Enums.Commons;using MediatR;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using Newtonsoft.Json;namespace DoctorLoan.Order.Application.Features.Commands;public class CallBackPayooCommandHandler : ApplicationBaseService<CallBackPayooCommandHandler>, IRequestHandler<CallBackPayooCommand, Result<bool>>{    private readonly PayooConfiguration _payooConfiguration;    public CallBackPayooCommandHandler(ILogger<CallBackPayooCommandHandler> logger, IApplicationDbContext context,                                    ICurrentRequestInfoService currentRequestInfoService,                                    ICurrentTranslateService currentTranslateService,                                    IDateTime dateTime,                                    PayooConfiguration payooConfiguration)    : base(logger, context, currentRequestInfoService, currentTranslateService, dateTime)    {        _payooConfiguration = payooConfiguration;    }    public async Task<Result<bool>> Handle(CallBackPayooCommand request, CancellationToken cancellationToken)    {        var _responseData = request.ResponseData;        if (_responseData == null) return Result.Failed<bool>(ServiceError.NotFound(_currentTranslateService));        if (_responseData.PaymentStatus != 1) return Result.Failed<bool>(ServiceError.NotFound(_currentTranslateService));        var checkSumKey = _payooConfiguration.CheckSumKey;        var payooIp = _payooConfiguration.SandboxIp; // sử dụng IP sandbox theo cấu hình hiện tại        var _hash = checkSumKey + JsonConvert.SerializeObject(_responseData) + payooIp;        var sha512Hash = ComputeSha512Hash(_hash);        bool isHashValid = sha512Hash.Equals(request.SecureHash, StringComparison.InvariantCultureIgnoreCase);        if (!isHashValid) return Result.Failed<bool>(ServiceError.NotFound(_currentTranslateService));        var order = await _context.Orders.FirstOrDefaultAsync(o => o.OrderNo == _responseData.OrderNo, cancellationToken);        if (order is null) return Result.Failed<bool>(ServiceError.NotFound(_currentTranslateService));        if (order.Status == OrderStatus.Completed && order.Status != OrderStatus.Return)            return Result.Success(false);        order.Status = OrderStatus.Confirm;        order.Remarks = "Đã thanh toán Payoo mã đơn: " + _responseData.OrderNo;        await _context.SaveChangesAsync(cancellationToken);        return Result.Success(true);    }    private string ComputeSha512Hash(string rawData)    {        var message = Encoding.UTF8.GetBytes(rawData);        using (var alg = SHA512.Create())        {            string hex = "";            var hashValue = alg.ComputeHash(message);            foreach (byte x in hashValue)            {                hex += String.Format("{0:x2}", x);            }            return hex;        }    }}
